import {STORAGE_KEY,defaultState,loadState,recordAttempt,recommendLevel,domains} from './core.js';
import {icon,esc,button,audioButton,companion,toast,speak,stopAudio,showDialog} from './ui.js';
import {renderReading,readingAction} from './reading.js';
import {renderMath,mathAction} from './math.js';
let storage;try{storage=localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error();}};}
export const ctx={state:loadState(storage),reading:null,math:null,save,render,go,start,finish,attempt,speak:(text,el,onEnd)=>speak(text,ctx.state.settings,el,onEnd),toast,showDialog};
let route=location.hash.slice(1)||'home',offlineReady=false,deferredInstall=null,storageWarning=false;
function save(){try{storage.setItem(STORAGE_KEY,JSON.stringify(ctx.state));}catch{if(!storageWarning){storageWarning=true;toast('No se puede guardar en este navegador. Mantén esta pestaña abierta y revisa el almacenamiento del dispositivo.');}}}
function go(to){stopAudio();if(location.hash.slice(1)===to){route=to;render();}else location.hash=to;}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'home';stopAudio();render();window.scrollTo(0,0);document.querySelector('main')?.focus({preventScroll:true});});
function start(kind,id,extra={}){if(['sum','subtract'].includes(kind)&&!ctx.state.guided?.includes(kind)){start('guide',kind,{nextTask:{kind,id}});return;}if(ctx.state.pending?.kind===kind&&ctx.state.pending.id===id&&!ctx.state.pending.finished){go('activity');return;}ctx.state.pending={kind,id,stage:0,errors:0,help:false,answer:'',selected:[],touched:[],...extra};save();go('activity');}
function attempt(domain,id,correct,extra={}){const p=ctx.state.pending||{};recordAttempt(ctx.state,{domain,id,title:p.title||id,correct,help:!!p.help,errors:p.errors||0,levelIndex:p.levelIndex,...extra});save();}
function finish(){const p=ctx.state.pending;if(!p)return;p.finished=true;if(ctx.state.session&&!p.sessionCounted){ctx.state.session.completed++;p.sessionCounted=true;}save();render();}
const countDomain=d=>ctx.state.history.filter(h=>h.domain===d).length;
function nav(){return [['home','home','Inicio'],['reading','book','Leo y descubro'],['math','math','Cuento y calculo'],['progress','leaf','Mis avances'],['family','family','Para familias']].map(([url,i,t])=>`<a href="#${url}" class="${route===url?'active':''}" ${route===url?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('');}
function shell(content){const s=ctx.state.settings;document.documentElement.style.setProperty('--scale',s.font);document.body.classList.toggle('reduce-motion',!s.motion);return `<header class="app-header"><a class="brand" href="#home"><img src="./assets/icon.svg" alt=""><span>La aventura de<br>leer y contar<small>Un poquito cada día</small></span></a><div class="header-actions"><span class="pill">${icon('leaf')} A tu ritmo</span><button class="icon-button" data-action="sound" aria-label="${s.sound?'Silenciar sonidos':'Activar sonidos'}" aria-pressed="${!s.sound}">${icon(s.sound?'sound':'mute')}</button><button class="icon-button" data-action="font" aria-label="Cambiar tamaño de letra">A<span style="font-size:.7em">A</span></button></div></header><nav class="nav" aria-label="Navegación principal">${nav()}</nav><main id="main" tabindex="-1">${content}</main><footer class="footer"><span id="offline-status">${offlineReady?'✓ Aventuras listas sin conexión':navigator.onLine?'Preparando las aventuras sin conexión…':'Sin conexión · usando el contenido guardado'}</span><button class="text-button" data-action="install">${icon('download')} Instalar aplicación</button></footer>`;}
function heading(eyebrow,title,subtitle=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><span class="pill">${icon('leaf')} Cada paso cuenta</span></div>`;}
function home(){const pending=ctx.state.pending&&!ctx.state.pending.finished;return `${heading('TU PEQUEÑA GRAN AVENTURA','¿Qué descubrimos hoy?','Un cuento, un reto y muchas cosas por descubrir.')}<div class="hero-grid"><section class="hero"><img class="hero-art" src="./assets/forest.webp" alt="Lía, una zorrita con un libro, en un bosque junto al río"><div class="hero-copy"><span class="chip">${icon('book')} El bosque de las historias</span><h2>Las aventuras<br>empiezan con<br>una palabra.</h2><p>Soy Lía. ¿Leemos y exploramos juntas?</p>${button((pending?'Continuar mi aventura':'¡Vamos a leer!')+icon('arrow'),pending?'resume':'first-story')}</div></section><aside class="session-card"><span class="sun" aria-hidden="true">☀</span><span class="eyebrow">UN RATITO PARA TI</span><h3>Pequeños pasos,<br>grandes descubrimientos</h3><p>${ctx.state.settings.duration} minutos orientativos. Puedes parar cuando quieras.</p>${button(icon('leaf')+' Mi sesión de hoy','session','secondary')}</aside></div><div class="section-title"><h2>Elige tu camino</h2><span>Con curiosidad y sin prisas</span></div><div class="entry-grid">${[['reading','book','Leo y descubro','Cuentos y juegos con palabras'],['math','math','Cuento y calculo','Números, sumas y restas'],['progress','leaf','Mis avances','Todo lo que voy practicando'],['family','family','Para familias','Acompañar y ajustar la aventura']].map(([url,i,t,sub])=>`<a class="entry" href="#${url}"><span class="entry-icon">${icon(i)}</span><h3>${t}</h3><p>${sub}</p><span class="arrow">${icon('arrow')}</span></a>`).join('')}</div>${companion('Equivocarse también es descubrir. Podemos probar otra vez, juntas.')}`;}
function completed(id){return ctx.state.history.some(h=>h.id===id);}
function readingCatalog(){const level=ctx.state.settings.readingLevel;return `${heading('EL BOSQUE DE LAS HISTORIAS','Leo y descubro','Lee, escucha y vuelve a leer. Aquí no hay prisa.')}<div class="tabs" aria-label="Nivel de lectura">${[1,2,3].map((n)=>`<button data-action="reading-level" data-value="${n}" class="${level===n?'selected':''}" aria-pressed="${level===n}">${['Frases sencillas','Pequeñas historias','Cuentos con diálogos'][n-1]}</button>`).join('')}</div><p class="subheading">${['Una o dos oraciones para empezar con confianza.','Historias de cuatro a seis oraciones, paso a paso.','Párrafos cortos, diálogos y pequeños misterios.'][level-1]} Puedes cambiar de nivel siempre que quieras.</p><div class="catalog-grid">${ctx.reading.stories.filter(x=>x.level===level).map((x,i)=>`<article class="catalog-card"><div class="card-illustration" aria-hidden="true">${['🌿','💧','🌼'][i]}</div><span class="eyebrow">AVENTURA ${i+1} ${completed(x.id)?'· YA PRACTICADA':''}</span><h3>${esc(x.title)}</h3><p>${x.sentences.length} frases · leer y comprender</p>${button('Abrir cuento '+icon('arrow'),'story','',`data-id="${x.id}"`)}</article>`).join('')}</div><div class="section-title"><h2>El taller de las palabras</h2><span>24 pequeñas aventuras</span></div><div class="catalog-grid">${[['order','Ordeno una frase','Palabras que encuentran su lugar'],['complete','La palabra que encaja','Lee y busca el sentido'],['intonation','Leo con expresión','Pausas, preguntas y exclamaciones'],['sound','Letras y sonidos','Descubre cómo suenan']].map(([type,title,sub])=>`<article class="catalog-card"><h3>${title}</h3><p>${sub}</p>${button('Elegir un reto','phrase-list','secondary',`data-type="${type}"`)}</article>`).join('')}</div>${companion('Si una palabra se complica, tócala. La miramos con calma.')}`;}
function phraseList(){const type=route.split('/')[1]||'order';return `${heading('TALLER DE LAS PALABRAS','Pequeños retos, grandes ideas')}<a class="text-button" href="#reading">← Volver a lectura</a><div class="catalog-grid spacer">${ctx.reading.phraseActivities.filter(x=>x.type===type).map((x,i)=>`<article class="catalog-card"><span class="eyebrow">RETO ${i+1}${completed(x.id)?' · PRACTICADO':''}</span><h3>${esc(x.title)}</h3>${button('Empezar','phrase','',`data-id="${x.id}"`)}</article>`).join('')}</div>`;}
function mathCatalog(){return `${heading('EL CLARO DE LOS NÚMEROS','Cuento y calculo','Toca, prueba y descubre. Las ayudas siempre están aquí.')}<div class="catalog-grid"><article class="catalog-card"><div class="card-illustration">🌱</div><h2>Contar hasta 100</h2><p>Objetos, series, decenas y un mapa de números.</p>${button('Vamos a contar '+icon('arrow'),'go','', 'data-route="counting"')}</article><article class="catalog-card"><div class="card-illustration">🍎</div><h2>Mis primeras sumas</h2><p>Juntar, añadir y descubrir cuántos hay ahora.</p>${button('Vamos a sumar '+icon('arrow'),'go','', 'data-route="sum"')}</article><article class="catalog-card"><div class="card-illustration">🎈</div><h2>Mis primeras restas</h2><p>Quitar algunos y contar los que quedan.</p>${button('Vamos a restar '+icon('arrow'),'go','', 'data-route="subtract"')}</article></div><div class="notice">Puedes empezar a sumar y restar con cantidades pequeñas. No necesitas contar hasta 100.</div>${companion('Podemos usar los dedos, fichas o juguetes. Pensar también es tocar y probar.')}`;}
function mathList(){const isCount=route==='counting',s=ctx.state.settings,band=isCount?s.countingBand:s.mathRange;const list=isCount?ctx.math.counting.filter(x=>x.band===band):ctx.math.arithmetic.filter(x=>x.kind===route&&x.range===band);return `${heading(isCount?'PASO A PASO':'JUNTAR Y QUITAR',isCount?'Contar hasta 100':route==='sum'?'Mis primeras sumas':'Mis primeras restas')}<a class="text-button" href="#math">← Volver a números</a><div class="tabs">${(isCount?[20,50,100]:[10,20]).map(n=>`<button data-action="math-level" data-value="${n}" data-kind="${isCount?'counting':'math'}" class="${band===n?'selected':''}" aria-pressed="${band===n}">Hasta ${n}</button>`).join('')}</div><div class="row">${isCount?button('Explorar la tabla del 1 al 100','go','secondary','data-route="hundred"'):button(icon('help')+' Ver un ejemplo guiado','guide','secondary',`data-kind="${route}"`)}${button('Elegir el siguiente reto para mí','next-recommended','',`data-kind="${isCount?'counting':route}"`)}</div><p class="muted spacer">Empieza donde te sientas cómoda. Puedes elegir cualquier reto o repetir uno.</p><div class="catalog-grid">${list.map((x,i)=>`<article class="catalog-card"><span class="eyebrow">${x.optional?'AMPLIACIÓN OPCIONAL':'RETO '+(i+1)}${completed(x.id)?' · PRACTICADO':''}</span><h3>${esc(x.title||x.prompt)}</h3><p>${isCount?({objects:'Toca y cuenta',quantity:'Cantidad y número',series:'Series',neighbors:'Antes y después',line:'Recta numérica',tens:'Decenas y unidades',continue:'Sigue contando',skip:'Contar a saltos'}[x.type]):({objects:'Objetos para tocar',line:'Saltos en la recta',symbols:'Números con ayudas',problem:'Un problema cotidiano'}[x.mode])}</p>${button('Probar este reto','math-task','secondary',`data-kind="${isCount?'counting':route}" data-id="${x.id}"`)}</article>`).join('')}</div>`;}
function stats(){return `<div class="progress-grid">${Object.entries(domains).map(([d,t])=>{const all=ctx.state.history.filter(h=>h.domain===d),independent=all.filter(h=>h.correct&&!h.help&&!h.errors).length;return `<article class="progress-card">${icon(d==='reading'?'book':d==='comprehension'?'leaf':'math')}<h3 class="spacer">${t}</h3><strong>${all.length}</strong><p>${d==='reading'?(all.length===1?'lectura practicada':'lecturas practicadas'):`${all.length===1?'reto resuelto':'retos resueltos'} · ${independent} sin ayuda`}</p></article>`;}).join('')}</div>`;}
function log(){return ctx.state.history.length?`<div class="log">${ctx.state.history.slice(-20).reverse().map(h=>`<div class="log-item"><div><strong>${esc(h.title)}</strong><br><span>${domains[h.domain]} · ${h.domain==='reading'?(h.observation==='independent'?'Adulto: leyó sin ayuda':h.observation==='supported'?'Adulto: necesitó ayuda':'Lectura practicada; sin valoración adulta'):(h.solutionShown?'Solución explorada':h.errors?'Resuelto tras volver a intentarlo':h.help?'Resuelto con ayuda':'Resuelto sin ayuda')}</span></div><span>${new Date(h.at).toLocaleDateString('es-ES')}</span></div>`).join('')}</div>`:`<div class="notice">Tu cuaderno está listo. Aquí aparecerán las actividades que vayas realizando.</div>`;}
function progress(){return `${heading('TU CUADERNO DE EXPLORACIÓN','Mis avances','Cada intento, cada pausa y cada nuevo descubrimiento cuentan.')}${stats()}<p class="muted spacer">Estos datos cuentan la práctica realizada, no una nota ni una prueba de dominio. Terminar una lectura no evalúa la pronunciación.</p><div class="section-title"><h2>Últimas aventuras</h2></div>${log()}${companion('Pedir ayuda y corregirte son dos buenas maneras de aprender.')}`;}
function family(){const s=ctx.state.settings;const select=(name,items)=>`<select data-setting="${name}">${items.map(([v,t])=>`<option value="${v}" ${String(s[name])===String(v)?'selected':''}>${t}</option>`).join('')}</select>`;const check=(name)=>`<input type="checkbox" data-setting="${name}" ${s[name]?'checked':''}>`;return `${heading('CRECER EN COMPAÑÍA','Para familias','Un espacio para acompañar, observar y adaptar.')}<div class="family-grid"><section class="panel"><h2>A su medida</h2><label class="field">Lectura ${select('readingLevel',[[1,'Frases sencillas'],[2,'Pequeñas historias'],[3,'Cuentos con diálogos']])}</label><label class="field">Conteo ${select('countingBand',[[20,'Hasta 20'],[50,'Hasta 50'],[100,'Hasta 100']])}</label><label class="field">Sumas y restas ${select('mathRange',[[10,'Hasta 10'],[20,'Hasta 20']])}</label><label class="field">Tamaño de letra ${select('font',[[1,'Grande'],[1.15,'Más grande'],[1.3,'Muy grande']])}</label><label class="field">Duración orientativa ${select('duration',[[5,'5 minutos'],[10,'10 minutos'],[12,'12 minutos'],[15,'15 minutos'],[20,'20 minutos']])}</label><label class="field">Sonido ${check('sound')}</label><label class="field">Reducir animaciones <input type="checkbox" data-setting="reduce" ${!s.motion?'checked':''}></label><label class="field">Adaptar el siguiente reto ${check('adaptive')}</label><p class="muted">Tras cinco retos, las respuestas, los errores y el uso de ayudas orientan el próximo reto sugerido. La lectura cambia solo por elección familiar. Siempre se puede elegir otro reto.</p></section><section class="panel"><h2>Un ratito juntas</h2><ul><li>Alternaos leyendo una frase. Escuchad un modelo y volved a leer sin correr.</li><li>Antes: hablad del título. Durante: parad y comentad qué está pasando. Después: contad por qué actuó un personaje.</li><li>Contad objetos reales tocando cada uno. El último número dice cuántos hay.</li><li>Representad sumas y restas con juguetes. Preguntad «¿qué ha cambiado?».</li><li>Celebrad estrategias: «Has vuelto a leer y has encontrado la pista».</li></ul><h3>Observar la lectura</h3><p>Después de leer, un adulto puede anotar si necesitó ayuda. Sin micrófono y sin reconocimiento de voz: pulsar «He vuelto a leer» solo registra práctica.</p><h3>Audio y conexión</h3><p>Se prioriza una voz española local del dispositivo. Si no está disponible, aparece una alternativa escrita. Algunas voces necesitan conexión. Podéis continuar leyendo juntos.</p>${button('Ver instalación y uso sin conexión','install','secondary')}</section></div><section class="panel spacer"><h2>En qué nos apoyamos</h2><div class="source"><a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/21" target="_blank" rel="noopener">Institute of Education Sciences · Guía de habilidades fundamentales de lectura</a><p>Recomienda relacionar sonidos y letras, aprender a leer palabras y practicar a diario con textos conectados. Esta guía se elaboró para la lectura en inglés. Aquí se adapta al español con sílabas revisadas y relaciones como «qu» en queso y «gu» en guitarra. No se trasladan mecánicamente reglas del inglés.</p></div><div class="source"><a href="https://educagob.educacionfpydeportes.gob.es/ca/curriculo/curriculo-lomloe/menu-curriculos-basicos/ed-primaria/areas/lengua-castellana/criterios-evaluacion-segundo-ciclo.html" target="_blank" rel="noopener">Ministerio de Educación · Lengua Castellana, segundo ciclo de Primaria</a><p>Orienta la comprensión antes, durante y después de leer, las inferencias sencillas y la lectura acompañada y expresiva. Usamos anticipaciones, preguntas sobre motivos, pausas y relecturas.</p></div><div class="source"><a href="https://www.gov.uk/government/publications/national-curriculum-in-england-mathematics-programmes-of-study/national-curriculum-in-england-mathematics-programmes-of-study" target="_blank" rel="noopener">Department for Education · Mathematics programmes of study</a><p>Propone contar hasta 100, avanzar y retroceder, usar objetos y rectas, y comprender decenas y unidades. Apoya una progresión entre representaciones concretas, dibujos y números.</p></div><h3>Decisiones de esta aplicación</h3><p>Las aventuras, Lía, las sesiones de 10–15 minutos, los tres tramos y la regla de adaptación son decisiones de diseño. Los cuentos y actividades son originales. Estas fuentes no avalan ni han evaluado la aplicación y no se prometen resultados.</p></section><section class="panel spacer"><h2>Actividad en este dispositivo</h2>${stats()}${log()}<div class="notice">Sin datos personales, publicidad, compras ni chat. El progreso se guarda solo en este navegador y dispositivo; no se sincroniza. Borrar los datos del navegador o usar navegación privada puede eliminarlo. Los enlaces de referencia necesitan conexión.</div>${button('Borrar todo el progreso','delete-ask','danger')}</section>`;}
function completeView(){const p=ctx.state.pending,s=ctx.state.session;return `<div class="activity"><div class="activity-card completion"><span class="medallion">${icon('leaf')}</span><span class="eyebrow">UN DESCUBRIMIENTO MÁS</span><h1>¡Has dedicado tiempo a aprender!</h1><p>${p.help||p.errors?'Has usado pistas y has vuelto a probar. Eso también es aprender.':'Has explorado con atención. Puedes descansar o seguir con otra aventura.'}</p>${s?`<p>Sesión: ${s.completed} ${s.completed===1?'actividad completada':'actividades completadas'}. ${s.completed>=3?'Ya has hecho la propuesta de hoy. ¡Buen momento para descansar!':'La propuesta de hoy tiene tres actividades.'}</p>`:''}<div class="row">${button(s&&s.completed<3?'Siguiente aventura de mi sesión':'Elegir otra aventura','next-adventure')}${button('Volver al inicio','go','secondary','data-route="home"')}</div></div>${companion('El esfuerzo importa. Aquí puedes seguir a tu ritmo.')}</div>`;}
function render(){const previous=document.activeElement;const anchor=previous?.dataset?.action?{...previous.dataset}:null;const setting=previous?.dataset?.setting;const isKeypad=previous?.closest?.('.keypad');const scrollAreas=[...document.querySelectorAll('.hundred,.numberline')].map(el=>({top:el.scrollTop,left:el.scrollLeft}));try{let content;if(route==='home')content=home();else if(route==='reading')content=readingCatalog();else if(route.startsWith('phrases/'))content=phraseList();else if(route==='math')content=mathCatalog();else if(['counting','sum','subtract'].includes(route))content=mathList();else if(route==='progress')content=progress();else if(route==='family')content=family();else if(route==='hundred')content=renderMath(ctx,'hundred');else if(route==='activity'&&ctx.state.pending){content=ctx.state.pending.finished?completeView():['story','phrase'].includes(ctx.state.pending.kind)?renderReading(ctx):renderMath(ctx);}else content=home();document.querySelector('#app').innerHTML=shell(content);document.querySelectorAll('.hundred,.numberline').forEach((el,i)=>{if(scrollAreas[i]){el.scrollTop=scrollAreas[i].top;el.scrollLeft=scrollAreas[i].left;}});if(anchor||setting){let next=setting?document.querySelector('[data-setting="'+setting+'"]'):[...document.querySelectorAll('[data-action]')].find(el=>Object.entries(anchor).every(([k,v])=>el.dataset[k]===v)&&!el.disabled);if(!next&&anchor?.action==='order')next=document.querySelector('[data-action="order"]')||document.querySelector('[data-action="read-check-order"]');if(!next)next=document.querySelector('.feedback button')||document.querySelector('.activity-card h1');if(next){if(next.tagName==='H1')next.tabIndex=-1;next.focus({preventScroll:true});}if(isKeypad){const details=document.querySelector('.keypad');if(details)details.open=true;}}}catch(e){console.error(e);document.querySelector('#app').innerHTML=shell(`<h1>Vamos a volver al camino</h1><p>Esta actividad no se ha podido abrir. Tu progreso guardado se conserva.</p><a class="btn" href="#home">Volver al inicio</a>`);}}
function firstUnfinished(list){return list.find(x=>!completed(x.id))||list[0];}
function suggested(kind){let list;if(kind==='reading'){const x=firstUnfinished(ctx.reading.stories.filter(x=>x.level===ctx.state.settings.readingLevel));start('story',x.id);return;}let levels=kind==='counting'?[20,50,100]:[10,20];const key=kind==='counting'?'countingBand':'mathRange';ctx.state.adaptiveLevels||={};let level=levels.indexOf(ctx.state.adaptiveLevels[kind]||ctx.state.settings[key]);if(ctx.state.settings.adaptive){const n=recommendLevel(ctx.state,kind,level,levels.length-1);if(n!==level)toast(n>level?'Probamos un reto un poco más amplio. Puedes cambiarlo en cualquier momento.':'Volvemos a una cantidad pequeña para practicar con calma.');level=n;ctx.state.adaptiveLevels[kind]=levels[level];save();}list=kind==='counting'?ctx.math.counting.filter(x=>x.band===levels[level]&&!x.optional):ctx.math.arithmetic.filter(x=>x.kind===kind&&x.range===levels[level]);start(kind,firstUnfinished(list).id);}
function installGuide(){if(deferredInstall){const prompt=deferredInstall;deferredInstall=null;prompt.prompt();prompt.userChoice.then(r=>{if(r.outcome!=='accepted')openInstallGuide();});}else openInstallGuide();}
function openInstallGuide(){const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;showDialog(`<h2>${standalone?'Tu aplicación está instalada':'Lleva la aventura contigo'}</h2><p><strong>Android · Chrome o Edge:</strong> abre la dirección segura de esta aplicación. Usa el menú ⋮ y «Instalar aplicación» o «Añadir a pantalla de inicio».</p><p><strong>iPhone o iPad · Safari:</strong> pulsa Compartir y «Añadir a pantalla de inicio». Activa «Abrir como app» si aparece y pulsa Añadir.</p><p><strong>Ordenador:</strong> en Chrome o Edge, usa el icono de instalación de la barra de direcciones.</p><div class="notice">${offlineReady?'✓ Los cuentos y retos ya están guardados para usarlos sin conexión.':'Espera a ver «Aventuras listas sin conexión» al pie de la página antes de desconectarte.'}</div><p>Ábrela desde su icono para verla en una ventana independiente. Necesita HTTPS para instalarse, salvo las pruebas en localhost. Las voces dependen del dispositivo; el texto y las actividades siguen disponibles.</p>${button('Entendido','close-modal')}`);}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main')?.focus();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;const p=ctx.state.pending;if(a==='go')go(b.dataset.route);else if(a==='sound'){ctx.state.settings.sound=!ctx.state.settings.sound;stopAudio();save();render();}else if(a==='font'){ctx.state.settings.font=ctx.state.settings.font===1?1.15:ctx.state.settings.font===1.15?1.3:1;save();render();}else if(a==='speak')ctx.speak(b.dataset.text);else if(a==='close-modal')document.querySelector('#modal').close();else if(a==='install')installGuide();else if(a==='first-story')suggested('reading');else if(a==='resume')go('activity');else if(a==='story'||a==='phrase')start(a,b.dataset.id);else if(a==='phrase-list')go('phrases/'+b.dataset.type);else if(a==='reading-level'){ctx.state.settings.readingLevel=+b.dataset.value;save();render();}else if(a==='math-level'){ctx.state.settings[b.dataset.kind==='counting'?'countingBand':'mathRange']=+b.dataset.value;ctx.state.adaptiveLevels||={};for(const kind of b.dataset.kind==='counting'?['counting']:['sum','subtract'])ctx.state.adaptiveLevels[kind]=+b.dataset.value;save();render();}else if(a==='math-task')start(b.dataset.kind,b.dataset.id);else if(a==='next-recommended')suggested(b.dataset.kind);else if(a==='guide')start('guide',b.dataset.kind);else if(a==='session'){ctx.state.session={started:Date.now(),completed:0,reminded:false};save();suggested('reading');}else if(a==='next-adventure'){const s=ctx.state.session;if(s&&s.completed<3)suggested(s.completed===1?'counting':'sum');else go(p?.kind==='story'||p?.kind==='phrase'?'reading':'math');}else if(a==='delete-ask')showDialog(`<h2>¿Borrar el progreso?</h2><p>Se borrarán las actividades registradas, la sesión pendiente y los ajustes de este dispositivo. Esta acción no se puede deshacer.</p><div class="row">${button('Conservar mi progreso','close-modal','secondary')}${button('Sí, borrar todo','delete-confirm','danger')}</div>`);else if(a==='delete-confirm'){ctx.state=defaultState();save();document.querySelector('#modal').close();go('home');toast('El progreso y los ajustes se han borrado.');}else if(!readingAction(ctx,a,b))mathAction(ctx,a,b);});
document.addEventListener('change',e=>{const key=e.target.dataset.setting;if(!key)return;const value=e.target.type==='checkbox'?e.target.checked:+e.target.value;if(key==='reduce')ctx.state.settings.motion=!value;else ctx.state.settings[key]=value;if(key==='countingBand'||key==='mathRange'){ctx.state.adaptiveLevels||={};for(const kind of key==='countingBand'?['counting']:['sum','subtract'])ctx.state.adaptiveLevels[kind]=value;}save();stopAudio();render();});
document.addEventListener('input',e=>{if(e.target.id==='numeric-answer'&&ctx.state.pending){ctx.state.pending.answer=e.target.value.replace(/\D/g,'').slice(0,3);e.target.value=ctx.state.pending.answer;save();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});window.addEventListener('appinstalled',()=>{deferredInstall=null;toast('La aventura ya tiene un lugar en tu pantalla de inicio.');});
window.addEventListener('online',()=>{toast('Conexión recuperada.');});window.addEventListener('offline',()=>{stopAudio();toast('Seguimos sin conexión. Los textos y los retos están aquí.');});
setInterval(()=>{const s=ctx.state.session;if(s&&!s.reminded&&Date.now()-s.started>=ctx.state.settings.duration*60000){s.reminded=true;save();toast('Ya ha pasado el ratito que elegiste. Puedes descansar cuando quieras.');}},15000);
try{[ctx.reading,ctx.math]=await Promise.all([fetch('./data/reading.json').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('./data/math.json').then(r=>{if(!r.ok)throw Error();return r.json();})]);render();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;offlineReady=true;const el=document.querySelector('#offline-status');if(el)el.textContent='✓ Aventuras listas sin conexión';}).catch(()=>{const el=document.querySelector('#offline-status');if(el)el.textContent='No se ha podido preparar el modo sin conexión. Vuelve a cargar con conexión.';});}}catch(e){document.querySelector('#app').innerHTML='<main class="loading"><h1>Necesitamos cargar la aventura</h1><p>Conéctate una vez para descargar los cuentos y los juegos completos.</p><button class="btn" onclick="location.reload()">Volver a cargar</button></main>';}
